		return 0, nil
	}
	return strconv.ParseInt(s, base, 64)
}

// Next advances to the next member of the archive.
func (rd *Reader) Next() (*Header, error) {
	if !rd.started {
		buf := make([]byte, len(globalHeader))
		if _, err := io.ReadFull(rd.r, buf); err != nil {
			if err == io.EOF {
				return nil, io.EOF
			}
			return nil, ErrInvalidGlobalHeader
		}
		if string(buf) != globalHeader {
			return nil, ErrInvalidGlobalHeader
		}
		rd.started = true
	}

	if skip := rd.remaining + rd.pad; skip > 0 {
		if _, err := io.CopyN(io.Discard, rd.r, skip); err != nil {
			if err == io.EOF {
				// the archive ends in the middle of the previous member
				return nil, io.ErrUnexpectedEOF
			}
			return nil, err
		}
	}
	rd.remaining, rd.pad = 0, 0

	buf := make([]byte, headerSize)
	if _, err := io.ReadFull(rd.r, buf); err != nil {
		return nil, err // io.EOF if at a clean member boundary
	}
	if string(buf[58:60]) != fileMagic {
		return nil, ErrInvalidHeader
	}

	hdr := &Header{Name: strings.TrimRight(string(buf[0:16]), " ")}
	fields := []struct {
		b    []byte
		base int
		set  func(int64)
	}{
		{buf[16:28], 10, func(v int64) { hdr.ModTime = time.Unix(v, 0) }},
		{buf[28:34], 10, func(v int64) { hdr.Uid = int(v) }},
		{buf[34:40], 10, func(v int64) { hdr.Gid = int(v) }},
		{buf[40:48], 8, func(v int64) { hdr.Mode = v }},
		{buf[48:58], 10, func(v int64) { hdr.Size = v }},
	}
	for _, f := range fields {
		v, err := parseField(f.b, f.base)
		if err != nil || v < 0 {
			return nil, ErrInvalidHeader
		}
		f.set(v)
	}

	rd.remaining = hdr.Size
	rd.pad = hdr.Size % 2
	return hdr, nil
}

// Read reads from the current member.
func (rd *Reader) Read(b []byte) (int, error) {
	if rd.remaining <= 0 {
		return 0, io.EOF
	}
	if int64(len(b)) > rd.remaining {
		b = b[:rd.remaining]
	}
	n, err := rd.r.Read(b)
	rd.remaining -= int64(n)
	if err == io.EOF && rd.remaining > 0 {
		err = io.ErrUnexpectedEOF
	}
	return n, err
}

// Writer writes an ar archive.
type Writer struct {
	w       io.Writer
	pending int64
	pad     bool
}

func NewWriter(w io.Writer) *Writer {
	return &Writer{w: w}
}

func (w *Writer) WriteGlobalHeader() error {
	_, err := io.WriteString(w.w, globalHeader)
	return err
}

func (w *Writer) WriteHeader(hdr *Header) error {
	if len(hdr.Name) > 16 {
		return ErrNameTooLong
	}
	if w.pending > 0 {
		return fmt.Errorf("ar: %d bytes of the previous member were not written", w.pending)
	}
	if w.pad {
		if _, err := w.w.Write([]byte{'\n'}); err != nil {
			return err
		}
		w.pad = false
	}
	var buf bytes.Buffer
	fmt.Fprintf(&buf, "%-16s%-12d%-6d%-6d%-8o%-10d%s", hdr.Name, hdr.ModTime.Unix(), hdr.Uid, hdr.Gid, hdr.Mode, hdr.Size, fileMagic)
	if _, err := w.w.Write(buf.Bytes()); err != nil {
		return err
	}
	w.pending = hdr.Size
	w.pad = hdr.Size%2 == 1
	return nil
}

func (w *Writer) Write(b []byte) (int, error) {
	if int64(len(b)) > w.pending {
		return 0, errors.New("ar: write too long")
	}
	n, err := w.w.Write(b)
	w.pending -= int64(n)
	return n, err
}
