// Copyright 2026 The Gitea Authors. All rights reserved.
// SPDX-License-Identifier: MIT

package ar

import (
	"bytes"
	"io"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestRoundTrip(t *testing.T) {
	var buf bytes.Buffer
	w := NewWriter(&buf)
	require.NoError(t, w.WriteGlobalHeader())
	files := []struct {
		name string
		data string
	}{{"debian-binary", "2.0\n"}, {"odd", "abc"}, {"control.tar.gz", "xyz12"}}
	for _, f := range files {
		require.NoError(t, w.WriteHeader(&Header{Name: f.name, Mode: 0o600, Size: int64(len(f.data))}))
		_, err := w.Write([]byte(f.data))
		require.NoError(t, err)
	}

	r := NewReader(&buf)
	for _, f := range files {
		hd, err := r.Next()
		require.NoError(t, err)
		assert.Equal(t, f.name, hd.Name)
		data, err := io.ReadAll(r)
		require.NoError(t, err)
		assert.Equal(t, f.data, string(data))
	}
	_, err := r.Next()
	assert.ErrorIs(t, err, io.EOF)
}

func TestMalformed(t *testing.T) {
	_, err := NewReader(bytes.NewReader([]byte("garbage!"))).Next()
	assert.ErrorIs(t, err, ErrInvalidGlobalHeader)

	// negative member size must be rejected instead of panicking
	data := globalHeader + "control.tar.gz   0           0     0     600     -1        `\n"
	r := NewReader(bytes.NewReader([]byte(data)))
	_, err = r.Next()
	assert.ErrorIs(t, err, ErrInvalidHeader)

	// truncated member
	data = globalHeader + "control.tar.gz   0           0     0     600     100       `\nabc"
	r = NewReader(bytes.NewReader([]byte(data)))
	_, err = r.Next()
	require.NoError(t, err)
	_, err = io.ReadAll(r)
	assert.ErrorIs(t, err, io.ErrUnexpectedEOF)
}
