export PATH=$PATH:/usr/local/go/bin
python3 - <<'EOF'
p='modules/packages/debian/ar/ar.go'
s=open(p).read()
old=s[s.index('	if skip := rd.remaining + rd.pad; skip > 0 {'):s.index('	rd.remaining, rd.pad = 0, 0\n')]
new='''	if rd.remaining > 0 {
		if _, err := io.CopyN(io.Discard, rd.r, rd.remaining); err != nil {
			if err == io.EOF {
				// the archive ends in the middle of the previous member
				return nil, io.ErrUnexpectedEOF
			}
			return nil, err
		}
	}
	if rd.pad > 0 {
		// some writers omit the padding byte after the final member
		if _, err := io.CopyN(io.Discard, rd.r, rd.pad); err != nil {
			return nil, err
		}
	}
'''
s=s.replace(old,new)
open(p,'w').write(s)
p='modules/packages/debian/ar/ar_test.go'
s=open(p).read()
s=s.replace('''"control.tar.gz   0           0     0     600     -1        `\\n"''','''rawHeader("control.tar.gz", "-1")''')
s=s.replace('''"control.tar.gz   0           0     0     600     100       `\\nabc"''','''rawHeader("control.tar.gz", "100") + "abc"''')
s=s.replace('func TestMalformed','''func rawHeader(name, size string) string {
	return fmt.Sprintf("%-16s%-12s%-6s%-6s%-8s%-10s`\\n", name, "0", "0", "0", "600", size)
}

func TestMalformed''')
s=s.replace('"bytes"\n','"bytes"\n\t"fmt"\n')
open(p,'w').write(s)
EOF
gofmt -l modules; go test ./modules/packages/debian/... 2>&1

